<template>
    <div class="col-sm-12 col-md-12 col-lg-12 ">
        <div class="row taskCard taskCard-bg" :class="[
          isDialog ? 'cursor-pointer' : 'cursor-default',
          { 'condition-card': isConditionCard }
        ]" @click="onCardClick(item)" @mouseenter="isHovering = true" @mouseleave="isHovering = false">
            <div class="col-sm-3 col-md-2 col-lg-2 verticalCenter">
              <q-btn round flat size="xs" class="p-10" :style="{ backgroundColor: showPlayIcon ? 'var(--primary)' : color }" @click.stop="handleTestCard">
                <!-- Show play icon on hover for condition cards -->
                <q-icon
                  v-if="showPlayIcon"
                  name="play_arrow"
                  color="white"
                  size="md"
                />
                <!-- Show default SVG icon otherwise -->
                <i
                  v-else
                  v-html="item.svg"
                  class="svg-icon center-inner "
                ></i>
              </q-btn>
            </div>
            <div class="col-sm-7 col-md-8 col-lg-8">
              <p class="color-93939A paddingMargin0 font-size-0-75 category-text" >{{ $t(item.category) }}
                <q-btn flat round color="grey" size="xs" icon="help" v-if="false">
                    <q-tooltip class="bg-indigo" anchor="top middle" self="bottom middle" :offset="[10, 10]">
                      {{ $t(item.category) }}
                    </q-tooltip>
                </q-btn>
              </p>
              <p class="paddingMargin0 font-size-15">
                <template v-if="!dataArray || dataArray.length < 1">
                  {{ cardPlainText }}
                </template>

                <template v-else>
                  <template v-for='(str, index) in dataArray' :key='index'>
                    <template v-if="renderBadge(str)">
                      <Badge :item="item" :variable="str" :isDialog="isDialog"/>
                    </template>
                    <template v-else-if="renderTextTranslation(str)">
                      {{ $t(str) }}
                    </template>
                    <template v-else>
                      {{ str + ' ' }}
                    </template>
                  </template>
                </template>

              </p>
            </div>
            <div class="col-sm-2 col-md-2 col-lg-2 verticalCenterCardMenus horizontalCenter" v-if="!isDialog">
              <q-btn
                :label="'v: ' + item.card_version"
                style="outline"
                size="xs"
                flat
                unelevated
                rounded
                no-wrap
                dense
                icon="sell"
                class="version-badge q-ml-xs highlight-text"
                @click.stop.prevent
              >
                <q-menu>
                  <q-list @click.stop.prevent>
                    <q-item clickable v-close-popup @click="$emit('changeCardVersion', version, item, itemIndex, cardType, indexAdditionals )" v-for="version in item.all_versions" :key="version">
                      <q-item-section>
                        <q-item-label>
                          {{ 'v: ' + version }}

                        </q-item-label>
                      </q-item-section>

                    </q-item>
                  </q-list>

                </q-menu>
              </q-btn>

              <q-icon name="more_horiz" class="more-horiz cursor-pointer" size="sm">
                <q-popup-proxy :offset="[10, 10]">
                  <q-list class="width-200 action-popup">
                    <q-item clickable v-close-popup @click="$emit('replaceCard', itemIndex, cardType, indexAdditionals)" class="item" >
                      <q-item-section>
                        <q-item-label>{{ $t('replace') }}</q-item-label>
                      </q-item-section>
                      <q-item-section side>
                        <q-icon name="sync" class="action-icon-muted" size="xs" />
                      </q-item-section>
                    </q-item>

                    <q-item clickable v-close-popup @click="$emit('testCard', item)" class="item" >
                      <q-item-section>
                        <q-item-label>{{ $t('wf_test_card') }}</q-item-label>
                      </q-item-section>
                      <q-item-section side>
                        <q-icon name="find_in_page" class="action-icon-muted" size="xs" />
                      </q-item-section>
                    </q-item>
                    
                    <div v-if="['additional_conditions', 'additional_executions'].includes(cardType)">
                      <q-separator class="action-separator" inset />
  
                      <q-item clickable v-close-popup @click="$emit('wf_moveAdditionals', 'right', indexAdditionals)" class="item" >
                        <q-item-section>
                          <q-item-label>{{ $t('wf_additionals_move_right') }}</q-item-label>
                        </q-item-section>
                        <q-item-section side>
                          <q-icon name="arrow_right" class="action-icon-muted" size="xs" />
                        </q-item-section>
                      </q-item>
  
                      <q-item clickable v-close-popup @click="$emit('wf_moveAdditionals', 'left', indexAdditionals)" class="item" >
                        <q-item-section>
                          <q-item-label>{{ $t('wf_additionals_move_left') }}</q-item-label>
                        </q-item-section>
                        <q-item-section side>
                          <q-icon name="arrow_left" class="action-icon-muted" size="xs" />
                        </q-item-section>
                      </q-item>
                    </div>

                    <q-separator class="action-separator" inset />

                    <q-item clickable v-close-popup @click="$emit('removeCard', itemIndex, cardType, indexAdditionals)" class="delete-item" >
                      <q-item-section>
                        <q-item-label>{{ $t('wf_delete_card') }}</q-item-label>
                      </q-item-section>
                      <q-item-section side>
                        <q-icon name="delete" class="action-icon-muted" size="xs" />
                      </q-item-section>
                    </q-item>
                  </q-list>
                </q-popup-proxy>
              </q-icon>
          </div>


        </div>
    </div>
</template>

<script lang="ts">

import Badge from 'src/pages/WorkflowBuilder/badge.vue';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import { workflowSplitDelimiter, splitDelimiter, workflowTranslationDelimiter } from 'src/constants';
import { resolveCardPlainText, prepareData as gcfprepareData } from 'src/pages/WorkflowBuilder/generic_card_functions';

export default defineComponent({
  name: 'generic-card',
  emits: ['onCardClick', 'removeCard', 'replaceCard', 'changeCardVersion', 'testCard', 'wf_moveAdditionals'],
  mixins: [helperUtil, helperMixin],
  components: { Badge },
  props: {
    isDialog: {
      type: Boolean,
      default: true,
    },
    itemIndex: {
      type: Number,
      default: null,
    },
    cardType: {
      type: String,
      default: '',
    },
    parentSvg: {
      type: String,
      default: '',
    },
    color: {
      type: String,
      default: '',
    },
    item: {
      type: Object,
      default: {
        category: '',
        id: '',
        text: '',
        toolTip: '',
        card_version: '',
      } as any,
    },
    indexAdditionals: {
      type: Number,
      default: 0,
    }
  },
  data() {
    return {
      showItemPanel: ref(false),
      dataArray: ref([] as string[]),
      isHovering: ref(false),
    };
  },

  computed: {
    cardPlainText(): string {
      return resolveCardPlainText(this.item);
    },
    isConditionCard() {
      return this.cardType === 'when' || this.cardType === 'and';
    },
    showPlayIcon() {
      return this.isConditionCard && this.isHovering;
    },
  },

  mounted() {
    this.prepareData();
  },
  // unmounted: function () {
  //   logInfo('unmounted');
  // },

  methods: {
    handleTestCard() {
      if (this.isConditionCard) {
        // Emit testCard event with card data
        this.$emit('testCard', this.item);
      }
    },

    renderBadge(str: string) {
      return str.startsWith(workflowSplitDelimiter);
    },

    renderTextTranslation(str: string) {
      return str.startsWith(workflowTranslationDelimiter);
    },

    prepareData() {
      this.dataArray = gcfprepareData(this.item);
    },
    onCardClick(item: any) {
      if(!this.isDialog) {
        return;
      }

      item.parentColor = this.color;

      this.$emit('onCardClick', item, this.indexAdditionals);
    },

  },
  setup() {

    return {

    }
  },
});
</script>

