<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { uid } from 'quasar';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import GenericCard from './generic-card.vue';
import helperUtil from 'src/utils/helperUtil';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin';
import { workflowApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets'
import { useWorkflowBuilderStore } from 'src/store/main';
import { CONSTANTS } from 'src/constants';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import WorkflowCardPickerDialog from './WorkflowComponnets/WorkflowCardPickerDialog.vue';

import workflowTemplates from 'src/pages/WorkflowBuilder/workflow_templates_view.vue'
import testCard from 'src/pages/WorkflowBuilder/workflow_test_card_view.vue'
import { i18n } from 'src/boot/i18n';
import { VueDraggableNext } from 'vue-draggable-next';
import {
  initWorkFlowMode as sharedInitWorkFlowMode,
  getComponentName as sharedGetComponentName,
  processCardVariablesForLoad,
  processVariablesForSave,
} from './workflow-variable-handler';
import { initChildDropdowns as sharedInitChildDropdowns } from './WorkflowComponnets/workflowDropdownInit';
import { downloadWorkflowJson } from 'src/pages/WorkflowBuilder/WorkflowComponnets/workflowImportExport';
import { filterLatestCardVersion as filterLatestCardVersionImpl, filterDeprecatedCards as filterDeprecatedCardsImpl, filterWorkflowVariableCards as filterWorkflowVariableCardsImpl, resolveCardSearch } from './composables/useCardPicker';
import { useWorkflowStoreSetup } from './composables/useWorkflowStoreSetup';
import { runWithBackendUnavailableWarning } from 'src/pages/WorkflowBuilder/composables/backendUnavailableWarning';

export default defineComponent({
  name: 'workflowDesigner',
  mixins: [helperUtil, helperMixin],
  components: {  Loader, GenericCard, workflowTemplates, SubHeader, testCard, draggable: VueDraggableNext, WorkflowCardPickerDialog },
  data() {
    return {
      saveWarnings: [] as any[],
      isWorkflowEnable: ref(true),
      workflowName: ref(''),
      workflowNameSelected: ref(false),
      workFlowId: ref(''),
      cardType: ref(''),
      cards: ref([] as any),
      category: ref([] as any),
      showItemPanel: ref(false),
      indexToRemove: ref((0 as number) || null),
      isWorkflowChanged: ref(false),
      criteriaValue: ref('after'),
      showAddCriteriaBox: ref(false),
      isConditionContent: ref(true),
      search_value: ref(''),
      version: ref(''),
      allCardsListForCardType: ref([] as any),
      selectedSubCategory: ref(false),
      activeSubCategory: ref(''),
      wf_version: ref(1 as number),
      wf_and_condition_break: ref((0 as number) || null),
      indexAdditionalsMain: ref(0 as number),
      additionalsLimit: 10 as number,
      incrementAndConditionBreak: ref(false),
      cardBlockDescriptions: ref({} as dynamicObj),
      cardBlockDescriptionsMaxLength: ref(200),
      cardBlockDescriptionsCounter: ref({} as dynamicObj),
      additionalColumnToDelete: ref(),
      confirmDeleteColumn: ref(false),
      separatorHeight: ref({} as dynamicObj),
      wf_alternates_table: ref(null),
      filteredCardsList: null as any,
    };
  },

  async mounted() {
    this.showLoading();
    this.wf_and_condition_break = null;
    this.indexToRemove = null;
    this.workFlowId = this.$route.params.id as string;
    try {
      await runWithBackendUnavailableWarning(async () => {
        // Fire the catalog, dropdown, and workflow-JSON fetches together; the
        // workflow JSON can be fetched in parallel but is processed
        // (applyWorkflow) only once the catalogs + dropdowns have settled,
        // since processing reads them.
        let workflowResponse: any = null;
        const loadTasks: Promise<unknown>[] = [
          this.getWorkflowAllCards(),
          this.initChildDropdowns(),
        ];
        if (this.workFlowId) {
          loadTasks.push(
            this.fetchWorkflow().then((response) => {
              workflowResponse = response;
            }),
          );
        }
        await Promise.allSettled(loadTasks);
        if (workflowResponse) {
          this.applyWorkflow(workflowResponse);
        }
      }, 'WorkflowDesignerV2');
    } catch (err) {
      console.error('[WorkflowDesignerV2] mount failed:', err);
    }

    setTimeout(this.updateSeparatorHeight, 500);
    window.addEventListener('wf_resize', this.updateSeparatorHeight);
    this.hideLoading();
    (<any>window).vpo = this;
    this.filteredCardsList = this.cards;
  },

  updated() {

    this.updateSeparatorHeight();
  },

  beforeUnmount() {
    window.removeEventListener('wf_resize', this.updateSeparatorHeight);
  },

  methods: {
    async initChildDropdowns() {
      await sharedInitChildDropdowns(this);
    },
    updateSeparatorHeight() {
      if (this.wf_version != 2) {
        return
      }
      try {
        // look how it is set at the start, text? field is of wrong size and messing up the lines
        this.separatorHeight['max'] = 0; // for additional condition cards
        this.separatorHeight['max_and'] = 0;  // for normal and cards
        if (!this.selectedAdditionalConditions) {
          return
        }
        for (let index = 0; index < this.selectedAdditionalConditions.length; index++) {
          this.separatorHeight[index] = 0;
        }
        this.$nextTick(() => {
          if (this.$refs.container_cards0) {
            this.separatorHeight['max_and'] = this.$refs['container_and'].firstChild.clientHeight > this.separatorHeight['max'] ? this.$refs['container_and'].firstChild.clientHeight : this.separatorHeight['max'];
            for (let index = 0; index <= this.selectedAdditionalConditions.length; index++) {
              if (this.$refs['container_cards' + index] && this.$refs['container_cards' + index][0]) {
                this.separatorHeight['max'] = this.$refs['container_cards' + index][0].firstChild.clientHeight > this.separatorHeight['max'] ? this.$refs['container_cards' + index][0].firstChild.clientHeight : this.separatorHeight['max'];
                this.separatorHeight['max'] = this.separatorHeight['max'] > this.separatorHeight['max_and'] ? this.separatorHeight['max'] : this.separatorHeight['max_and'];
              }
            }
            for (let index = 0; index <= this.selectedAdditionalConditions.length; index++) {
              if (this.$refs['container_cards' + index] && this.$refs['container_cards' + index][0]) {
                this.separatorHeight[index] = this.separatorHeight['max'] - this.$refs['container_cards' + index][0].firstChild.clientHeight
              }
            }
            this.separatorHeight['and'] = this.separatorHeight['max'] - this.$refs['container_and'].firstChild.clientHeight
          }
        })
      } catch (err) {
        console.error(err)
        this.separatorHeight = {};
      }
    },
    setCardType(cardType: string, indexAdditionals = 0, incrementAndConditionBreak = false) {
      this.cards = [] as any[];
      this.cardType = cardType;
      this.filteredCardsList.cards = [] as any[];
      this.filteredCardsList.category = [] as any[];
      this.filteredCardsList.cardType = cardType;
      this.search_value = '';
      this.indexAdditionalsMain = indexAdditionals;
      this.incrementAndConditionBreak = incrementAndConditionBreak;

      if (cardType == CONSTANTS.when) {

        this.category = this.workflowWhenCards;
        this.filteredCardsList = this.workflowWhenCards;
        this.displayAllCards();

      } else if (cardType == CONSTANTS.and || cardType == CONSTANTS.additional_conditions) {

        this.category = this.workflowAndCards;
        this.filteredCardsList = this.workflowAndCards;
        this.displayAllCards();

      } else if (cardType == CONSTANTS.then || cardType == CONSTANTS.additional_executions) {

        this.category = this.workflowThenCards;
        this.filteredCardsList = this.workflowThenCards;
        this.displayAllCards();
      }
      this.activeSubCategory = '';
      this.showItemPanel = true;
    },

    displayAllCards() {
      this.allCardsListForCardType = [];
      for (let category_card of this.category) {
        this.setSubCategory(category_card)
        const sub_category_cards = this.filteredCardsList.cards
        for (let sub_category_card of sub_category_cards) {
          sub_category_card.svg_background_color = category_card.svg_background_color
          this.allCardsListForCardType.push(sub_category_card)
        }
      }
      this.selectedSubCategory = false;
      this.filteredCardsList.cards = this.allCardsListForCardType
    },

    changeCardVersionWhen(card_version: string, card: any, itemIndex: any, cardType: string) {
      let card_to_change = [] as any;
      let when_category = this.workflowWhenCards.filter((when_category: any) => {
        return when_category.category == card.category
      });
      card_to_change = when_category[0].cards.filter((card_to_change: any) => {
        return (card_to_change.card_version == card_version && card_to_change.id == card.id)
      });
      card_to_change = card_to_change[0]
      card_to_change.parentColor = card.parentColor
      this.removeCard(itemIndex, cardType)
      this.setCardType(cardType)
      this.onCardClick(JSON.parse(JSON.stringify(card_to_change)))
    },
    changeCardVersionAndThen(card_version: string, card: any, itemIndex: any, cardType: string, indexAdditionals = 0) {
      let card_to_change = [] as any;
      if (cardType == CONSTANTS.and || cardType == CONSTANTS.additional_conditions) {
        let and_category = this.workflowAndCards.filter((and_category: any) => {
          return and_category.category == card.category
        });
        card_to_change = and_category[0].cards.filter((card_to_change: any) => {
          return (card_to_change.card_version == card_version && card_to_change.id == card.id)
        });
      } else if (cardType == CONSTANTS.then || cardType == CONSTANTS.additional_executions) {
        let then_category = this.workflowThenCards.filter((then_category: any) => {
          return then_category.category == card.category
        });
        card_to_change = then_category[0].cards.filter((card_to_change: any) => {
          return (card_to_change.card_version == card_version && card_to_change.id == card.id)
        });
      }
      card_to_change = card_to_change[0];
      card_to_change.parentColor = card.parentColor;
      this.replaceCard(itemIndex, cardType, indexAdditionals);
      this.setCardType(cardType, indexAdditionals);
      this.onCardClick(JSON.parse(JSON.stringify(card_to_change)));
    },

    addNewAlternateExecution(and_condition_break: number | null = null) {
      if (this.selectedAdditionalConditions.length >= this.additionalsLimit) {
        notify.error(i18n.t('wf_additionals_limit_reached', { 'limit': this.additionalsLimit }));
        return
      }
      if (
        this.selectedAdditionalExecutions &&
        this.selectedAdditionalExecutions.length > 0 &&
        this.selectedAdditionalExecutions[this.selectedAdditionalExecutions.length - 1].length == 0
      ) { // missing then card
        notify.error(i18n.t('wf_previous_execution_needs_cards'))
        return
      } else if (
        this.selectedAdditionalConditions &&
        this.selectedAdditionalConditions.length > 0 &&
        this.selectedAdditionalConditions[this.selectedAdditionalConditions.length - 1].length == 0
      ) { // catch else (always goes to then)
        notify.error(i18n.t('wf_only_one_without_additional_conditions'))
        return
      }
      this.wf_version = 2;
      this.wf_and_condition_break = and_condition_break;
      this.selectedAdditionalConditions.push([] as any[]);
      this.selectedAdditionalExecutions.push([] as any[]);
      this.updateSeparatorHeight();
      this.scrollToNewPosition();
    },
    scrollToNewPosition() {
      this.$nextTick(() => {
        const tableContainer = this.$refs.wf_alternates_table.$el;
        tableContainer.scrollTo({
          left: tableContainer.scrollWidth,
          behavior: 'smooth'
        })
      }
      )
    },
    removeAlternateExecution(alternateIndex: number) {
      for (let i = alternateIndex; i < this.selectedAdditionalConditions.length - 1; i++) {
        this.cardBlockDescriptions['additionals_and_' + i] = this.cardBlockDescriptions['additionals_and_' + (i + 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_and_' + (i + 1)])) : '';
        this.cardBlockDescriptions['additionals_then_' + i] = this.cardBlockDescriptions['additionals_then_' + (i + 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_then_' + (i + 1)])) : '';
      }
      this.selectedAdditionalConditions.splice(alternateIndex, 1);
      this.selectedAdditionalExecutions.splice(alternateIndex, 1);
      // remove last one
      if (this.cardBlockDescriptions['additionals_and_' + this.selectedAdditionalConditions.length]) {
        delete this.cardBlockDescriptions['additionals_and_' + this.selectedAdditionalConditions.length];
      }
      if (this.cardBlockDescriptions['additionals_then_' + this.selectedAdditionalExecutions.length]) {
        delete this.cardBlockDescriptions['additionals_then_' + this.selectedAdditionalExecutions.length];
      }
      if (this.selectedAdditionalConditions && this.selectedAdditionalConditions.length == 0) {
        this.resetWorkflowVersion();
      }
    },

    resetWorkflowVersion() {
      this.wf_and_condition_break = null;
      this.cardBlockDescriptions['and'] = '';
      this.wf_version = 1;
    },

    resetShowCards() {
      this.incrementAndConditionBreak = false;
      this.cleanWorkflowModel()
    },

    moveAdditionals(direction: string, indexAdditionals: number) {
      const move_text_and = this.cardBlockDescriptions['additionals_and_' + indexAdditionals] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_and_' + indexAdditionals])) : '';
      const move_text_then = this.cardBlockDescriptions['additionals_then_' + indexAdditionals] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_then_' + indexAdditionals])) : '';
      if (direction == 'left') {
        if (indexAdditionals == 0 || !this.selectedAdditionalConditions[indexAdditionals] || this.selectedAdditionalConditions[indexAdditionals].length == 0) {
          notify.error(i18n.t('wf_additionals_cannot_move_left'))
          return
        }
        const left_text_and = this.cardBlockDescriptions['additionals_and_' + (indexAdditionals - 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_and_' + (indexAdditionals - 1)])) : '';
        const left_text_then = this.cardBlockDescriptions['additionals_then_' + (indexAdditionals - 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_then_' + (indexAdditionals - 1)])) : '';
        const move_conditions = JSON.parse(JSON.stringify(this.selectedAdditionalConditions.splice(indexAdditionals, 1)[0]));
        const move_executions = JSON.parse(JSON.stringify(this.selectedAdditionalExecutions.splice(indexAdditionals, 1)[0]));
        this.selectedAdditionalConditions.splice(indexAdditionals - 1, 0, move_conditions);
        this.selectedAdditionalExecutions.splice(indexAdditionals - 1, 0, move_executions);
        this.cardBlockDescriptions['additionals_and_' + (indexAdditionals - 1)] = move_text_and;
        this.cardBlockDescriptions['additionals_then_' + (indexAdditionals - 1)] = move_text_then;
        this.cardBlockDescriptions['additionals_and_' + indexAdditionals] = left_text_and;
        this.cardBlockDescriptions['additionals_then_' + indexAdditionals] = left_text_then;
      }
      else if (direction == 'right') {
        if (indexAdditionals == this.selectedAdditionalConditions.length - 1) {
          notify.error(i18n.t('wf_additionals_cannot_move_right_last'))
          return
        } else if (!this.selectedAdditionalConditions[indexAdditionals + 1] || this.selectedAdditionalConditions[indexAdditionals + 1].length == 0) {
          notify.error(i18n.t('wf_additionals_cannot_move_right_empty'))
          return
        } else {
          const right_text_and = this.cardBlockDescriptions['additionals_and_' + (indexAdditionals + 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_and_' + (indexAdditionals + 1)])) : '';
          const right_text_then = this.cardBlockDescriptions['additionals_then_' + (indexAdditionals + 1)] ? JSON.parse(JSON.stringify(this.cardBlockDescriptions['additionals_then_' + (indexAdditionals + 1)])) : '';
          const move_conditions = JSON.parse(JSON.stringify(this.selectedAdditionalConditions.splice(indexAdditionals, 1)[0]));
          const move_executions = JSON.parse(JSON.stringify(this.selectedAdditionalExecutions.splice(indexAdditionals, 1)[0]));
          this.selectedAdditionalConditions.splice(indexAdditionals + 1, 0, move_conditions);
          this.selectedAdditionalExecutions.splice(indexAdditionals + 1, 0, move_executions);
          this.cardBlockDescriptions['additionals_and_' + (indexAdditionals + 1)] = move_text_and;
          this.cardBlockDescriptions['additionals_then_' + (indexAdditionals + 1)] = move_text_then;
          this.cardBlockDescriptions['additionals_and_' + indexAdditionals] = right_text_and;
          this.cardBlockDescriptions['additionals_then_' + indexAdditionals] = right_text_then;
        }
      }
      this.updateSeparatorHeight();
    },

    checkCardVersion(card: any, cardType: string) {
      let versions = [] as any[]
      versions.join(card.card_version)

      if (cardType == CONSTANTS.when) {

        const category_cards = this.workflowWhenCards

        category_cards.forEach((category: any) => {
          category.forEach((entry: any) => {
            if (entry.id == card.id) {
              versions.join(entry.card_version)
            }
          })
        })

      } else if (cardType == CONSTANTS.and) {

        this.category = this.workflowAndCards;
        this.filteredCardsList = this.workflowAndCards;

      } else if (cardType == CONSTANTS.then) {

        this.category = this.workflowThenCards;
        this.filteredCardsList = this.workflowThenCards;

      }
    },

    filterLatestCardVersion() {
      filterLatestCardVersionImpl(this.filteredCardsList);
    },
    filterDeprecatedCards() {
      filterDeprecatedCardsImpl(this.filteredCardsList);
    },
    filterWorkflowVariableCards() {
      filterWorkflowVariableCardsImpl(this.filteredCardsList);
    },

    setSubCategory(cards: any) {
      if (this.cards == cards && this.selectedSubCategory) {
        this.selectedSubCategory = false;
        this.inputSearchValueChanges(this.search_value);
        this.activeSubCategory = ''
        return
      }
      this.version = ''
      this.selectedSubCategory = true;
      this.activeSubCategory = cards.category
      if (cards) {
        this.cards = cards;
        this.filteredCardsList.cards = cards.cards;
        this.inputSearchValueChanges(this.search_value)
      }
    },
    onCardClick(itemToAdd: any, indexAdditionals: number | null = null) {
      const clonedItem = JSON.parse(JSON.stringify(itemToAdd));
      clonedItem.uuid = uid();
      clonedItem.indexAdditionals = indexAdditionals ? indexAdditionals != null : this.indexAdditionalsMain
      if (indexAdditionals == null) {
        indexAdditionals == this.indexAdditionalsMain;
      }
      for (let variable of clonedItem.variables) {
        variable.uuid = uid();
        variable.componentName = this.getComponentName(variable.display_name);
        this.initWorkFlowMode(variable, true);
      }

      if (this.cardType == CONSTANTS.when) {

        this.selectedWhenCards = clonedItem;

      } else if (this.cardType == CONSTANTS.and) {
        if (this.indexToRemove || this.indexToRemove == 0) {
          this.selectedAndCards.splice(this.indexToRemove, 1);
          this.selectedAndCards.splice(this.indexToRemove, 0, clonedItem);
        } else if (this.incrementAndConditionBreak && this.wf_and_condition_break != undefined && this.wf_and_condition_break != null) {
          this.selectedAndCards.splice((this.wf_and_condition_break + 1), 0, clonedItem);
          this.wf_and_condition_break += 1;
          this.resetShowCards();

        } else {

          this.selectedAndCards.push(clonedItem);
        }

      } else if (this.cardType == CONSTANTS.then) {

        if (this.indexToRemove || this.indexToRemove == 0) {
          this.selectedThenCards.splice(this.indexToRemove, 1);
          this.selectedThenCards.splice(this.indexToRemove, 0, clonedItem);
        } else {

          this.selectedThenCards.push(clonedItem);
        }
      } else if (this.cardType == CONSTANTS.additional_conditions) {

        if (this.indexToRemove || this.indexToRemove == 0) {
          this.selectedAdditionalConditions[this.indexAdditionalsMain].splice(this.indexToRemove, 1);
          this.selectedAdditionalConditions[this.indexAdditionalsMain].splice(this.indexToRemove, 0, clonedItem);
        } else {
          this.selectedAdditionalConditions[this.indexAdditionalsMain].push(clonedItem);
        }
      } else if (this.cardType == CONSTANTS.additional_executions) {

        if (this.indexToRemove || this.indexToRemove == 0) {
          this.selectedAdditionalExecutions[this.indexAdditionalsMain].splice(this.indexToRemove, 1);
          this.selectedAdditionalExecutions[this.indexAdditionalsMain].splice(this.indexToRemove, 0, clonedItem);
        } else {
          this.selectedAdditionalExecutions[this.indexAdditionalsMain].push(clonedItem);
        }
      }

      this.indexToRemove = null;
      this.showItemPanel = false;
      this.activeSubCategory = ''
    },
    getSelectedCardVarUUIDsByCardLocation(selectedCards: any[]): string[] {
      let var_uuids_in_use = [] as string[];
      for (const card of selectedCards) {
        var_uuids_in_use = var_uuids_in_use.concat(this.getCardVarUUIDs(card));
      }
      return var_uuids_in_use;
    },
    cleanWorkflowModel() {
      // clean workflowmodel of unused vars
      let var_uuids_in_use = [] as string[];
      if (this.selectedWhenCards) {
        var_uuids_in_use = var_uuids_in_use.concat(this.getCardVarUUIDs(this.selectedWhenCards))
      }
      if (this.selectedAndCards) {
        var_uuids_in_use = var_uuids_in_use.concat(this.getSelectedCardVarUUIDsByCardLocation(this.selectedAndCards));
      }
      if (this.selectedThenCards) {
        for (const card of this.selectedThenCards) {
          var_uuids_in_use = var_uuids_in_use.concat(this.getCardVarUUIDs(card))
        }
        var_uuids_in_use = var_uuids_in_use.concat(this.getSelectedCardVarUUIDsByCardLocation(this.selectedThenCards));
      }
      if (this.wf_version == 2) {
        if (this.selectedAdditionalConditions) {
          for (let index = 0; index < this.selectedAdditionalConditions.length; index++) {
            var_uuids_in_use = var_uuids_in_use.concat(this.getSelectedCardVarUUIDsByCardLocation(this.selectedAdditionalConditions[index]));
          }
        }
        if (this.selectedAdditionalExecutions) {
          for (let index = 0; index < this.selectedAdditionalExecutions.length; index++) {
            var_uuids_in_use = var_uuids_in_use.concat(this.getSelectedCardVarUUIDsByCardLocation(this.selectedAdditionalExecutions[index]));
          }
        }
      }

      for (const var_uuid_key of Object.keys(this.workflowModel)) {
        if (!var_uuids_in_use.includes(var_uuid_key)) {
          delete this.workflowModel[var_uuid_key]
        }
      }
    },
    getCardVarUUIDs(card: any): string[] {
      let var_uuids = [] as string[];
      if (!card.variables) {
        return var_uuids;
      }
      for (const variable of card.variables) {
        if (variable.uuid) {
          var_uuids.push(variable.uuid)
        }
      }
      return var_uuids
    },
    removeCard(indexToRemove: number, cardType: string, indexAdditionals = 0) {
      this.indexAdditionalsMain = indexAdditionals;
      this.cardType = cardType;
      if (this.cardType == CONSTANTS.when) {

        this.selectedWhenCards = {};

      } else if (this.cardType == CONSTANTS.and) {

        this.selectedAndCards.splice(indexToRemove, 1);
        if (indexToRemove == this.wf_and_condition_break) {
          this.wf_and_condition_break -= 1;
        }

      } else if (this.cardType == CONSTANTS.then) {

        this.selectedThenCards.splice(indexToRemove, 1);
      } else if (this.cardType == CONSTANTS.additional_conditions) {
        if (indexToRemove == 0 && this.selectedAdditionalConditions[this.indexAdditionalsMain].length == 0) {
          notify.error(i18n.t('wf_last_condition_cannot_be_removed'))
          return
        }
        this.selectedAdditionalConditions[this.indexAdditionalsMain].splice(indexToRemove, 1)
      } else if (this.cardType == CONSTANTS.additional_executions) {
        if (indexToRemove == 0 && this.selectedAdditionalExecutions[this.indexAdditionalsMain].length == 0) {
          notify.error(i18n.t('wf_last_condition_cannot_be_removed'))
          return
        }
        this.selectedAdditionalExecutions[this.indexAdditionalsMain].splice(indexToRemove, 1)
      }
      this.updateSeparatorHeight();
    },
    replaceCard(indexToRemove: number, cardType: string, indexAdditionalsMain = 0) {
      this.indexToRemove = indexToRemove;
      this.indexAdditionalsMain = indexAdditionalsMain;
      this.setCardType(cardType, indexAdditionalsMain);
    },
    validateSaveJson(): boolean {

      if (!this.workflowName) {
        notify.error(this.$t('NAME_MANDATORY'));
        return false;
      }

      if (this.selectedWhenCards && Object.keys(this.selectedWhenCards).length < 1) {
        notify.error(i18n.t('wf_when_card_missing'));
        return false;
      }

      if (this.selectedThenCards && this.selectedThenCards.length < 1) {
        notify.error(i18n.t('wf_then_card_missing'));
        return false;
      }

      if (this.wf_version > 1) {
        if (!this.selectedAndCards || this.selectedAndCards.length == 0) {
          notify.error(i18n.t('wf_and_card_needed'))
          return false;
        }

        if (this.selectedAdditionalConditions) {
          for (let i = 0; i < (this.selectedAdditionalConditions.length - 1); i++) { // ignore last, else
            if (this.selectedAdditionalConditions[i].length == 0) {
              notify.error(i18n.t('wf_and_card_missing_at_position', { 'position': i + 1 }))
              return false;
            }
          }
        }

        if (this.selectedAdditionalConditions.length != this.selectedAdditionalExecutions.length) {
          notify.error(i18n.t('wf_unequal_additionals'))
          return false;
        }

        if (!this.selectedAndCards || this.selectedAndCards.length - 1 == this.wf_and_condition_break) {
          notify.error(i18n.t('wf_needs_additional_and_condition'))
          return false;
        }
        if (this.selectedAdditionalExecutions) {
          for (let index = 0; index < this.selectedAdditionalExecutions.length; index++) {
            if (!this.selectedAdditionalExecutions[index] || this.selectedAdditionalExecutions[index].length == 0) {
              notify.error(i18n.t('wf_then_card_missing_at_position', { 'position': index + 1 })) // + 1 for default case, not in additionals
              return false;
            }
          }
        }
        if (
          (this.selectedAdditionalConditions.length == 0 && this.selectedAdditionalExecutions.length == 0) ||
          (this.selectedAdditionalConditions[this.selectedAdditionalConditions.length - 1].length == 0 &&
            this.selectedAdditionalExecutions[this.selectedAdditionalExecutions.length - 1].length == 0)
        ) {
          this.selectedAdditionalConditions.pop();
          this.selectedAdditionalExecutions.pop();
          if (
            this.selectedAdditionalConditions.length == 0 &&
            this.selectedAdditionalExecutions.length == 0
          ) {
            this.resetWorkflowVersion();
          }
        }
      }

      return true;

    },
    
    async downloadWorkflow() {
      try {
        this.showLoading();
        await downloadWorkflowJson(this.workFlowId, this.workflowName);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async saveWorkflowTemplate() {
      if (!this.validateSaveJson()) {
        return;
      }
      this.showLoading();
      await this.saveTemplateJson();
      this.hideLoading();
      if (this.workFlowId.length > 10) {
        this.$router.push('/template_designer/' + this.workFlowId);
      }
    },
    async saveWorkflow() {

      if (!this.validateSaveJson()) {
        return;
      }

      this.showLoading();

      let isWorkFlowCreated: boolean | null = false;

      const currentPath: string = this.$router.currentRoute.value.path;
      if (this.isWorkflowChanged || currentPath.includes('template') || !this.workFlowId) {
        isWorkFlowCreated = await this.createWorkflow();

        if (isWorkFlowCreated == null || isWorkFlowCreated == undefined) {
          this.hideLoading();
          return;
        }

        // A failed update returns above and keeps the flag set for a retry.
        this.isWorkflowChanged = false;
      }

      // A create already saved the card JSON in the same request.
      if (!isWorkFlowCreated) {
        await this.saveWorkflowJson();
      }
      this.hideLoading();

      if (isWorkFlowCreated) {
        this.$router.push('/workflow_designer/' + this.workFlowId);
      }

    },
    async createWorkflow(): Promise<boolean | null> {
      let isNewCase = null as null | boolean;
      try {

        if (this.workflowName.length < 3) {
          throw { message: 'WF_NAME_ATLEAST_3_CHAR' }
        }

        if (this.workFlowId && this.$router.currentRoute.value.path.includes('workflow_designer')) {

          await workflowApiService.updateWorkflow({ name: this.workflowName, id: this.workFlowId });
          isNewCase = false;

        } else {
          // Without a workflow_id the save endpoint creates the workflow in the same request.
          const workFlowJson: any = await this.prepareWorkFlowJsonToSave();
          delete workFlowJson.workflow_id;
          const response: any = await workflowApiService.saveWorkflowJson(workFlowJson);

          if (!response.success) {
            throw response;
          }

          this.workFlowId = response.workflow_id;
          this.handleSaveResponse(response);
          isNewCase = true;
        }

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
        isNewCase = null;

      }

      // false (updated, nothing created) must stay distinct from null
      // (failure), or the caller skips the card save after every rename.
      return isNewCase;
    },
    // Show save warnings (SaveResponse.warnings) in a small popup; plain
    // success toast when there are none. Local to v2 — standard workflows
    // have no canvas nodes, so this just lists the messages.
    handleSaveResponse(response: any) {
      const warnings = response.warnings || [];
      if (!warnings.length) {
        this.saveWarnings = [];
        notify.success(this.$t('MSG_SAVE'));
        return;
      }
      // Show the warnings in a top banner — the same mechanism the advanced
      // designer uses: an HTML card that lists each warning on its own line,
      // dismissable via the close button. No notify/VNode workarounds.
      this.saveWarnings = warnings;
    },
    async saveWorkflowJson() {
      let response: any;
      try {
        let workFlowJson = await this.prepareWorkFlowJsonToSave();
        response = await workflowApiService.saveWorkflowJson(workFlowJson);

        if (!response.success) {
          throw response;
        }

        if (response.success) {
          this.handleSaveResponse(response);
        }

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
      }
    },
    async saveTemplateJson() {
      let response: any;
      try {
        const workFlowJson = await this.prepareWorkFlowJsonToSave();
        let templateJson = {
          'template_id': workFlowJson.workflow_id,
          'data': workFlowJson.data,
          'name': this.workflowName
        };
        response = await workflowApiService.saveWorkflowTemplateJSON(templateJson);

        if (!response.success) {
          throw response;
        }

        if (response.success) {
          notify.success(this.$t('MSG_SAVE'));
          this.workFlowId = response.workflow.id
        }

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
      }
    },

    testCard(item: any) {
      this.cardToTest = item;
      this.ShowTestCardDialog = true;
    },

    async prepareWorkFlowJsonToSave() {

      let whenCondition = JSON.parse(JSON.stringify(this.selectedWhenCards));
      let andCondition = JSON.parse(JSON.stringify(this.selectedAndCards));
      let thenCondition = JSON.parse(JSON.stringify(this.selectedThenCards));

      let additionalConditions = (this.selectedAdditionalConditions && this.selectedAdditionalExecutions) ? JSON.parse(JSON.stringify(this.selectedAdditionalConditions)) : null;
      let additionalExecutions = (this.selectedAdditionalConditions && this.selectedAdditionalExecutions) ? JSON.parse(JSON.stringify(this.selectedAdditionalExecutions)) : null;

      // Process WHEN card
      this.deleteCardData(whenCondition);
      whenCondition.variables = await processVariablesForSave(
        whenCondition.variables,
        this.workflowModel,
        this.docOperatorVariables,
        this.docOperatorVariablesSensitive,
        this.docOperatorLockedSensitiveData
      );

      // Process AND cards
      for (let card of andCondition) {
        this.deleteCardData(card);
        card.variables = await processVariablesForSave(
          card.variables,
          this.workflowModel,
          this.docOperatorVariables,
          this.docOperatorVariablesSensitive,
          this.docOperatorLockedSensitiveData
        );
      }

      // Process THEN cards
      for (let card of thenCondition) {
        this.deleteCardData(card);
        card.variables = await processVariablesForSave(
          card.variables,
          this.workflowModel,
          this.docOperatorVariables,
          this.docOperatorVariablesSensitive,
          this.docOperatorLockedSensitiveData
        );
      }

      // Process additional conditions and executions
      if (additionalConditions && additionalExecutions) {
        try {
          for (let additional_block of [additionalConditions, additionalExecutions]) {
            for (let part_block of additional_block) {
              for (let card of part_block) {
                this.deleteCardData(card);
                card.variables = await processVariablesForSave(
                  card.variables,
                  this.workflowModel,
                  this.docOperatorVariables,
                  this.docOperatorVariablesSensitive,
                  this.docOperatorLockedSensitiveData
                );
              }
            }
          }

        } catch (err) {
          console.error(err)
        }
      }

      // Clean up empty descriptions
      if (this.cardBlockDescriptions) {
        for (const key of Object.keys(this.cardBlockDescriptions)) {
          if (this.cardBlockDescriptions[key] == '') {
            delete this.cardBlockDescriptions[key];
          }
        }
      }

      const workFlowJson = {
        'workflow_id': this.workFlowId,
        'data': {
          'when_condition': whenCondition,
          'and_conditions': andCondition,
          'then_conditions': thenCondition,
          'and_condition_break': this.wf_and_condition_break,
          'additional_and_conditions': additionalConditions,
          'additional_then_executions': additionalExecutions,
          'descriptions': JSON.parse(JSON.stringify(this.cardBlockDescriptions)),
        },
        'version': this.wf_version,
        'name': this.workflowName
      };

      return workFlowJson;

    },
    deleteCardData(card: any) {
      delete card.parentColor;
      delete card.svg;
      delete card.category;
      delete card.svg_background_color;
      // delete card.text;
    },
    inputSearchValueChanges(search_value: any) {
      this.filteredCardsList.cards = resolveCardSearch(
        search_value,
        this.selectedSubCategory,
        this.cards?.cards || null,
        this.allCardsListForCardType,
        this.$t,
      );
      this.filterDeprecatedCards();
      this.filterLatestCardVersion();
      this.filterWorkflowVariableCards();
    },
    inputValueChanges() {
      this.isWorkflowChanged = true;
    },
    // Fetch-only: no dependency on the card catalogs / dropdowns, so it can run
    // in parallel with getWorkflowAllCards + initChildDropdowns. Returns the
    // raw response (or null on failure) for applyWorkflow to process afterward.
    async fetchWorkflow() {
      try {
        if (JSON.parse(JSON.stringify(this.$router.currentRoute.value.path)).includes('template')) {
          return await workflowApiService.loadWorkflowTemplateJson(this.workFlowId);
        }
        return await workflowApiService.loadworkflowJson(this.workFlowId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
        return null;
      }
    },
    // Processing step: reads the card catalogs + dropdown data, so it must run
    // only after those have settled.
    applyWorkflow(response: any) {
      try {
        if (response.success) {
          this.prepareWorkFlowJsonToDisplay(response)
        }

        if (response.data && response.data.error_logs && response.data.error_logs.errors === true) {
          throw { message: 'workflow_card_issue' };
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(i18n.t(msg));
        logError(err);
      }
    },
    prepareWorkFlowJsonToDisplay(response: any) {
      this.wf_version = response.version ? response.version : 1;
      this.workflowName = response.name;
      this.isWorkflowEnable = response.enabled;

      this.selectedWhenCards = response.data && response.data.when_condition ? response.data.when_condition : {};
      this.selectedAndCards = response.data && response.data.and_conditions ? response.data.and_conditions : [];
      this.selectedThenCards = response.data && response.data.then_conditions ? response.data.then_conditions : [];

      this.selectedAdditionalConditions = response.data && response.data.additional_and_conditions ? response.data.additional_and_conditions : [];
      this.selectedAdditionalExecutions = response.data && response.data.additional_then_executions ? response.data.additional_then_executions : [];
      this.wf_and_condition_break = response.data && response.data.and_condition_break != null ? response.data.and_condition_break : null;
      this.wf_version = response && response.wf_version >= 1 ? response.wf_version : 1;
      this.cardBlockDescriptions = response.data && response.data.descriptions ? response.data.descriptions : {};

      // Prepare map to collect cards color
      let cardDetailsMap = new Map();

      for (let cards of this.workflowWhenCards) {
        cardDetailsMap.set(cards.category, cards.svg_background_color);
      }

      for (let cards of this.workflowAndCards) {
        cardDetailsMap.set(cards.category, cards.svg_background_color);
      }

      for (let cards of this.workflowThenCards) {
        cardDetailsMap.set(cards.category, cards.svg_background_color);
      }

      // Process WHEN card
      if (this.selectedWhenCards && Object.keys(this.selectedWhenCards).length > 0) {
        this.selectedWhenCards.parentColor = cardDetailsMap.get(this.selectedWhenCards.category);
        this.selectedWhenCards.uuid = uid();

        processCardVariablesForLoad(
          this.selectedWhenCards,
          this.docOperatorVariables,
          this.docOperatorLockedSensitiveData,
          this.setDocOperatorVariables,
          this.doc_operator_prompts,
          this.getComponentName,
          this.workflowModel
        );
      }

      // Process AND cards
      for (let card of this.selectedAndCards) {
        card.parentColor = cardDetailsMap.get(card.category);
        card.uuid = uid();

        processCardVariablesForLoad(
          card,
          this.docOperatorVariables,
          this.docOperatorLockedSensitiveData,
          this.setDocOperatorVariables,
          this.doc_operator_prompts,
          this.getComponentName,
          this.workflowModel
        );
      }

      // Process THEN cards
      for (let card of this.selectedThenCards) {
        card.parentColor = cardDetailsMap.get(card.category);
        card.uuid = uid();

        processCardVariablesForLoad(
          card,
          this.docOperatorVariables,
          this.docOperatorLockedSensitiveData,
          this.setDocOperatorVariables,
          this.doc_operator_prompts,
          this.getComponentName,
          this.workflowModel
        );
      }

      // Process additional conditions
      if (this.selectedAdditionalConditions && this.selectedAdditionalExecutions) {
        for (const additionals of this.selectedAdditionalConditions) {
          for (let card of additionals) {
            card.parentColor = cardDetailsMap.get(card.category);
            card.uuid = uid();

            processCardVariablesForLoad(
              card,
              this.docOperatorVariables,
              this.docOperatorLockedSensitiveData,
              this.setDocOperatorVariables,
              this.doc_operator_prompts,
              this.getComponentName,
              this.workflowModel
            );
          }
        }

        // Process additional executions
        for (const additionals of this.selectedAdditionalExecutions) {
          for (let card of additionals) {
            card.parentColor = cardDetailsMap.get(card.category);
            card.uuid = uid();

            processCardVariablesForLoad(
              card,
              this.docOperatorVariables,
              this.docOperatorLockedSensitiveData,
              this.setDocOperatorVariables,
              this.doc_operator_prompts,
              this.getComponentName,
              this.workflowModel
            );
          }
        }
      }

      this.updateSeparatorHeight()
    },
    initWorkFlowMode(variable: any, isDefaultElement: boolean) {
      sharedInitWorkFlowMode(this.workflowModel, variable, isDefaultElement, this.docOperatorVariables);
    },
    getComponentName(display_name: string) {
      return sharedGetComponentName(display_name);
    },

  },
  setup() {
    const shared = useWorkflowStoreSetup();

    // v2-specific store refs
    const workflow_builder_store = useWorkflowBuilderStore();
    const {
      selectedAdditionalConditions,
      selectedAdditionalExecutions,
    } = storeToRefs(workflow_builder_store);

    return {
      ...shared,
      selectedAdditionalConditions,
      selectedAdditionalExecutions,
    }
  },
});
</script>

