<template class="col-12 q-pb-md workflow-height-limit">
  <q-card class="standard-popup-size">
    <q-card-section class="row background-color">
      <q-toolbar
        class="secondary-toolbar"
        style="margin-top: -10px; margin-bottom: -10px"
      >
        <q-toolbar-title>
          <span class="text-weight-bold text-white">{{
            $t('wf_test_workflow_card')
          }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" color="white" v-close-popup />
      </q-toolbar>
    </q-card-section>

    <q-card-section class="row">
      <q-input
        v-model="searchDocumentBy"
        dense
        :class="
          searchDocumentBy.length === 0 ? 'search-in-active' : 'search-active'
        "
        class="col-6"
        autofocus
        :placeholder="$t('search')"
        outlined
        @update:model-value="inputValueChangesDocumentSearch()"
        style="padding-right: 5px"
      >
        <template v-slot:append>
          <q-icon flat dense name="search" size="24px" color="primary" />
        </template>
      </q-input>
    </q-card-section>

    <q-card-section>
      <q-markup-table
        v-if="tableDataDocuments.length > 0"
        flat
        bordered
        separator="cell"
        class="doc-test-table-style sticky-header"
        wrap-cells
      >
        <thead>
          <q-tr>
            <q-th class="text-left">{{ $t('document_name') }}</q-th>
            <q-th class="text-left">{{ $t('doc_status') }}</q-th>
            <q-th class="text-left">{{ $t('assigned_to') }}</q-th>
            <q-th class="text-left">{{ $t('last_modified_on') }}</q-th>
            <q-th class="text-left"></q-th>
          </q-tr>
        </thead>
        <tbody
          class="text-left"
          v-for="doc in tableDataDocuments"
          :key="doc.id"
        >
          <q-tr class="text-left">
            <q-td class="text-left">
              {{ doc.filename }}
            </q-td>
            <q-td class="text-left">
              {{ $t(doc.status) }}
            </q-td>
            <q-td class="text-left">
              {{ doc.assigned_to }}
            </q-td>
            <q-td class="text-left">
              {{ formatDateAccordingToPreference(doc.last_modified_on) }}
            </q-td>
            <q-td class="text-center">
              <f-btn @click="runCardOnDoc(doc.id)">{{
                $t('wf_testCardOnDoc')
              }}</f-btn>
            </q-td>
          </q-tr>
          <q-tr />
          <q-tr
            class="text-left"
            v-if="Object.keys(test_result || {}).includes(doc?.id)"
            v-show="Object.keys(test_result || {}).includes(doc?.id)"
          >
            <q-td colspan="1" class="text-center">
              <div
                v-if="(test_result || {})[doc?.id || '']?.result === 'success'"
              >
                <q-icon :name="'check_circle'" :color="'green'" size="md" />
                <div>{{ $t('wf_success') }}</div>
              </div>
              <div
                v-else-if="
                  (test_result || {})[doc?.id || '']?.result === null ||
                  (test_result || {})[doc?.id || '']?.result ===
                    'failed_condition'
                "
              >
                <q-icon
                  :name="'do_not_disturb_on'"
                  :color="'orange'"
                  size="md"
                />
                <div>{{ $t('wf_failed_condition') }}</div>
              </div>
              <div v-else>
                <q-icon :name="'cancel'" :color="'red'" size="md" />
                <div>{{ $t('wf_error') }}</div>
              </div>
            </q-td>
            <q-td colspan="4">
              <div style="font-weight: bold">{{ $t('wf_card_logs') }}:</div>
              <div
                v-for="log in (test_result || {})[doc?.id || '']?.logs"
                v-bind:key="log.message"
              >
                <span v-if="log.translation_key">{{
                  $t('wf_log_' + log.translation_key, translateData(log.data))
                }}</span>
                <span v-else>{{ log.message }}</span>
              </div>
            </q-td>
          </q-tr>
          <q-tr />
        </tbody>
      </q-markup-table>
      <div v-else>
        {{ $t('wf_search_document_to_test') }}
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { debounce } from 'quasar';
import { storeToRefs } from 'pinia';
import dateUtils from 'src/utils/date';
import { defineComponent, ref } from 'vue';
import helperUtil from 'src/utils/helperUtil';
import helperMixin from 'src/mixins/helperMixin';
import { ApiExceptions } from 'src/exceptions/index';
import { documentListApiService, workflowApiService } from 'src/services';
import { useWorkflowBuilderStore } from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import { i18n } from 'src/boot/i18n';
export default defineComponent({
  name: 'testCard',
  mixins: [helperUtil, helperMixin, dateUtils],
  data() {
    return {
      tableDataDocuments: {} as any,
      searchDocumentBy: ref(''),
    };
  },

  mounted() {
    this.debounceSearchInputFunc = debounce(() => {
      this.searchDocument();
    }, 1000);

    this.searchDocument();
  },

  methods: {
    inputValueChangesDocumentSearch() {
      this.debounceSearchInputFunc();
    },

    async searchDocument() {
      let response: any;
      try {
        this.showLoading();
        if (this.searchDocumentBy.length > 1) {
          response = await documentListApiService.getList(
            `?keyword=${this.searchDocumentBy}`,
          );

          if (response.documents) {
            this.tableDataDocuments = response.documents;
          }
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    translateData(data: dynamicObj) {
      const data_keys = Object.keys(data);
      for (let data_key of data_keys) {
        let values_to_translate: string[] = data[data_key].split(', ');
        for (let i = 0; i < values_to_translate.length; i++) {
          values_to_translate[i] = i18n.t(
            values_to_translate[i],
            i18n.t(
              values_to_translate[i].toLowerCase(),
              values_to_translate[i],
            ),
          );
        }
        data[data_key] = values_to_translate.join(', ');
      }
      return data;
    },

    async runCardOnDoc(doc_id: string) {
      this.prepareCardData();
      try {
        this.showLoading();
        let response: any;
        this.request_params = {} as dynamicObj;
        ((this.request_params['doc_id'] = doc_id),
          (this.request_params['change_doc'] = false),
          (this.request_data = {} as dynamicObj));
        this.request_data['card_data'] = this.cardToTestVarsSet;

        response = await workflowApiService.runCardForDocument(
          this.request_data,
          this.request_params,
        );
        this.test_result[doc_id] = response;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    prepareCardData() {
      this.cardToTestVarsSet = this.cardToTest;

      for (
        let var_index = 0;
        var_index < this.cardToTestVarsSet.variables.length;
        var_index++
      ) {
        if (
          this.workflowModel[this.cardToTestVarsSet.variables[var_index].uuid]
            .value
        ) {
          this.cardToTestVarsSet.variables[var_index].data =
            this.workflowModel[
              this.cardToTestVarsSet.variables[var_index].uuid
            ].value.toString();
        } else {
          this.cardToTestVarsSet.variables[var_index].data = '';
        }
      }
    },
  },
  setup() {
    const workflow_builder_store = useWorkflowBuilderStore();
    const { workflowModel, cardToTest } = storeToRefs(workflow_builder_store);

    return {
      ShowTestCardDialog: ref(false),
      loading: ref(false),
      formData: {} as FormData,
      debounceSearchInputFunc: {} as any,
      request_params: ref({} as dynamicObj),
      request_data: ref({} as dynamicObj),
      documents: ref([] as any),
      test_result: ref({} as dynamicObj),

      workflowModel,
      cardToTest,
      cardToTestVarsSet: ref({} as dynamicObj),
    };
  },
});
</script>

